	allegiance = "前暮光之锤成员",
	aliases = { "塞尔杜林" },
	sections = {
		{
			title = "概述",
			text = [=[迷失者塞尔杜林是一名{link:dwarves}矮人{/link}，曾是{link:twilight-s-hammer}暮光之锤{/link}的成员。他在那个教派中得知的某些东西击碎了他的心智，于是他背叛了它。他逃走时，带走了{link:myzrael}密斯莱尔{/link}的卷轴，密斯莱尔是被巨人束缚在{link:arathi-highlands}阿拉希高地{/link}之下的存在。如今他藏身于{link:badlands}废土{/link}。他自言自语，对着虚无发笑，然后为此道歉，接着又收回道歉。在疯狂之下，他怕得要命，而他确实有理由害怕。]=],
		},
		{
			title = "意义",
			text = [=[塞尔杜林证明了{link:twilight-s-hammer}暮光之锤{/link}所侍奉的力量是常人的心智无法承受的。他知道他昔日的教派在等待什么，并把阻止它当作自己的使命。他所恐惧的不只是{link:myzrael}密斯莱尔{/link}。他还提到了其他存在，远比她古老，他不肯大声说出它们的名字，生怕它们会听到。]=],
		},
		{
			title = "事迹",
			text = [=[• 他从{link:twilight-s-hammer}暮光之锤{/link}那里偷走了{link:myzrael}密斯莱尔{/link}的卷轴。
• 在狂怒的{link:elements}元素{/link}将卷轴撕碎之后，他把它修补完整。
• 他在{link:uldaman}奥达曼{/link}中寻找{link:farmer-ray}雷{/link}乌纳石板，还寻找一位名叫亚戈因的古代作者所写的文摘。
• 他通过出示昔日教派的标志——锤之印记——冒充他们的一员。]=],
		},
		{
			title = "未载之事",
			text = [=[没有任何记录提到塞尔杜林的氏族、他在{link:twilight-s-hammer}暮光之锤{/link}中的岁月，或是他究竟看到了什么而心智崩溃。]=],
		},
	},
	chapters = {
		{
			title = "撕碎的卷轴",
			hint = "找回密斯莱尔卷轴的碎片。",
			text = [=[{link:twilight-s-hammer}暮光之锤{/link}的仆从前来寻找卷轴。塞尔杜林手里并没有它。狂怒的{link:elements}元素{/link}从他手中夺走了卷轴，如今正为了碎片相互争斗。碎片被找回来后，他用一把废料棘轮着手工作，把卷轴拼合起来。他希望一切还不算太晚。]=],
		},
		{
			title = "公主的枷锁",
			hint = "从疯子那里了解如何再次束缚密斯莱尔。",
			text = [=[塞尔杜林说，{link:myzrael}密斯莱尔{/link}已经获得自由，正在积聚力量。必须在她强大到足以打击囚禁她的人之前将她召唤出来并击败她。他昔日教派中的一些人以为他们能控制她。他问了一个显而易见的问题：如果她可以被控制，巨人为什么要用锁链锁住她？]=],
		},
		{
			title = "雷乌纳石板",
			hint = "把深藏在奥达曼的石板带给疯子。",
			text = [=[塞尔杜林说，一场末日即将来临，而他不忍说出将带来末日的那些存在的名字。他派一名搜寻者进入{link:uldaman}奥达曼{/link}，去寻找一块藏在一个比任何{link:dwarves}矮人{/link}造物都古老的箱子里的石板。石板被带回来时，他欣喜若狂。然后他读了它，而这还不够。]=],
		},
		{
			title = "亚戈因的文摘",
			hint = "把他昔日教派所保管的文摘带给疯子。",
			text = [=[{link:twilight-s-hammer}暮光之锤{/link}在许多地方都保存着亚戈因的文摘，教派中博学的成员研读着它。塞尔杜林把锤之印记交给他的搜寻者，派他们去找他昔日教派在{link:ironforge}铁炉堡{/link}和{link:undercity}幽暗城{/link}的保管者。文摘终于回到了他手中。他满怀希望地流泪赞颂。然后，他在同一口气里警告说，如果那些隐藏者一旦崛起，就不会有人活到抱上孙辈的那一天。]=],
		},
	},
	mentions = {
		{ text = "迷失者塞尔杜林" },
		{ text = "失落的碎片" },
		{ text = "召唤公主" },
		{ text = "末日的解答" },
		{ text = "飞往{link:ironforge}铁炉堡{/link}取亚戈因的文摘" },
		{ text = "飞往{link:undercity}幽暗城{/link}取亚戈因的文摘" },
		{ text = "星辰、手与心" },
		{ text = "禁忌的知识" },
	},
	bonds = {
		{ id = "myzrael", name = "密斯莱尔", note = "他偷走了她的卷轴" },
		{ id = "zaruk", name = "萨鲁克", note = "他昔日教派的成员，在落锤镇" },
		{ id = "gerrig-bonegrip", name = "葛利·硬骨", note = "在铁炉堡保管文摘" },
		{ id = "keeper-bel-dugur", name = "保管者贝尔杜加", note = "在幽暗城保管文摘" },
	},
})

Translate("zhCN", "prospector-ryedol", {
	title = "勘察员雷杜尔",
	subtitle = "探险者协会勘探员",
	found = "铁趾挖掘场以南的协会营地",
	hint = "找到在铁趾挖掘场陷落中幸存下来的勘探员。",
	allegiance = "探险者协会",
	aliases = { "雷杜尔" },
	sections = {
		{
			title = "概述",
			text = [=[勘察员雷杜尔曾在探险家铁趾·格{link:farmer-ray}雷{/link}兹手下工作，参与他在{link:badlands}废土{/link}北部的挖掘。暗炉氏族发动袭击时，他是少数逃脱的人之一。如今他与{link:sigrun-ironhew}西格鲁·铁斧{/link}和其他幸存者一起，在被毁的挖掘场以南维持着一个小营地。他说话直白，满脸疲惫，说在废土的每一天都是糟糕的一天。]=],
		},
		{
			title = "意义",
			text = [=[雷杜尔是把铁趾的命运与{link:ironforge}铁炉堡{/link}联系在一起的那根线。通过他，王国得知暗炉氏族不只是在劫掠。他们在搜寻泰坦的秘密，以及铁趾装在脑子里的知识。]=],
		},
		{
			title = "事迹",
			text = [=[• 他逃过了暗炉氏族对{link:hammertoe-s-digsite}铁趾挖掘场{/link}的袭击。
• 他从一张潦草的地图上得知铁趾被活着带到了{link:uldaman}奥达曼{/link}。
• 他派一名搜寻者进入宝库，寻找他的老主人。
• 他托人把铁趾的护符带给{link:ironforge}铁炉堡{/link}的{link:historian-karnik}史学家卡尼克{/link}。]=],
		},
		{ title = "未载之事", text = "关于雷杜尔来到{link:badlands}废土{/link}之前的生活，没有任何记载。" },
	},
	chapters = {
		{
			title = "幸运镐",
			hint = "从暗炉氏族手中夺回勘探员的镐。",
			text = [=[雷杜尔在袭击中失去了一切，连他的幸运镐也丢了。他相信是一个暗炉{link:dwarves}矮人{/link}拿走了它。镐被送回来时，他心怀感激。但他也感到不安。他说，{link:dark-iron-dwarves}黑铁矮人{/link}并不是随意袭击挖掘场的。他们在寻找某样东西。]=],
		},
		{
			title = "希望的迹象",
			hint = "告诉勘探员那张粉笔地图揭示了什么。",
			text = [=[人们在被毁的挖掘场附近发现了一张地图，上面用粉笔潦草地写着一条消息：铁趾正被带往{link:uldaman}奥达曼{/link}。雷杜尔本已为他哀悼，以为他死了。现在他明白暗炉氏族为何饶他一命。他们想要铁趾所知道的关于泰坦挖掘的一切。{link:dark-iron-dwarves}黑铁矮人{/link}长久以来一直在寻找制造更强大傀儡的方法。铁趾研究过同样的秘密，为的是阻止他们。]=],
		},
		{
			title = "信仰的展望",
			hint = "把铁趾留下的东西带给勘探员。",
			text = [=[人们在{link:uldaman}奥达曼{/link}找到了铁趾，但他已奄奄一息。他把自己的护符——他毕生的心血——送了回来，并要求把它交给雷杜尔。雷杜尔说，当他以为主人已经死了的时候，他反而更快乐些。然后他振作起来。铁趾曾与{link:ironforge}铁炉堡{/link}的{link:historian-karnik}史学家卡尼克{/link}共事，卡尼克会知道这枚护符意味着什么。雷杜尔把它转送给他，好让这一死不至于白费。]=],
		},
	},
	mentions = {
		{ text = "{link:dwarves}矮人{/link}和他的工具" },
		{ text = "希望的迹象" },
		{ text = "希望的迹象，派往{link:uldaman}奥达曼{/link}" },
		{ text = "信仰的展望，铁趾的护符被送回" },
		{ text = "信仰的展望，转送{link:ironforge}铁炉堡{/link}" },
	},
	bonds = {
		{ id = "hammertoe-grez", name = "铁趾·格雷兹", note = "他的主人" },
		{ id = "sigrun-ironhew", name = "西格鲁·铁斧", note = "与他同住一个营地" },
		{ id = "historian-karnik", name = "史学家卡尼克", note = "铁趾在铁炉堡的搭档" },
	},
})

