			text = [=[大地之印由{link:angor-fortress}苦痛堡垒{/link}的{link:dark-iron-dwarves}黑铁矮人{/link}所造，用来束缚{link:deathwing}死亡之翼{/link}的两名副官，即双生幼龙{link:blacklash}布莱克拉什{/link}和{link:hematus}赫玛图斯{/link}。它被带到{link:garek-bandarion}加瑞克{/link}面前时，他说话变得坦率了些。黑龙已经来到峡谷中筑巢。{link:ogres}食人魔{/link}竟然偷走了大地之印。牢狱已不再可靠。]=],
